package net.civeira.phylax.features.access.useraccesstemporalcode.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.crypto.KeyRingSecretStorage;

class TempSecondFactorSeedVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property temp second factor seed of user access temporal code ")
  void test_temp_second_factor_seed_v_o_builder() {
    KeyRingSecretStorage service = Mockito.mock(KeyRingSecretStorage.class);
    Mockito
        .when(
            service.seal("small", "access.user_access_temporal_code.temp_second_factor_seed#owner"))
        .thenReturn("sealed:k0:example");
    Assertions.assertEquals("sealed:k0:example", TempSecondFactorSeedVO.fromPlain("small")
        .getTempSecondFactorSeedStored(service, "owner").orElse(null));
    Assertions.assertEquals("****", TempSecondFactorSeedVO.fromPlain("small").toString());
  }
}
